.hero:before,.hero:after{content:"";pointer-events:none;position:absolute;z-index:0;opacity:.23;border:1px solid rgba(255,255,255,.75)}
.hero:before{width:min(61vw,940px);height:min(61vw,940px);border-radius:50%;left:-28%;top:-60%;box-shadow:0 0 0 36px rgba(255,255,255,.09),0 0 0 72px rgba(255,255,255,.055),0 0 0 116px rgba(255,255,255,.035)}
.hero:after{width:55vw;max-width:780px;height:55vw;max-height:780px;border-radius:50%;right:-30%;bottom:-98%;transform:rotate(-22deg) scaleX(.68);box-shadow:0 0 0 30px rgba(255,255,255,.075),0 0 0 64px rgba(255,255,255,.045)}
.hero .hero-centered{position:relative;z-index:1;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;min-height:570px;padding:116px 0}
.hero h1{font-size:clamp(56px,7vw,104px);font-weight:850;letter-spacing:-.055em;line-height:1.08;margin:0 0 18px;white-space:nowrap}
.hero .hero-tagline{font-size:clamp(17px,2vw,26px);line-height:1.4;font-weight:350;letter-spacing:-.025em;max-width:none;color:#fff;margin:0 0 26px;white-space:nowrap}
.hero .hero-description{font-size:clamp(14px,1.25vw,16px);line-height:1.7;font-weight:400;max-width:920px;color:#fff;margin:0 0 35px;white-space:nowrap}
.hero .hero-actions{justify-content:center;margin-top:0}
.audience-section{padding-top:104px;padding-bottom:104px}
.audience-section .section-top{margin-bottom:28px}
.audience-list{gap:14px;margin-top:26px;align-items:stretch}
.audience-item{padding:0 0 25px;min-height:172px;display:flex;flex-direction:column;background:#fff}
.audience-item:after{display:none}
.audience-item .audience-title{margin:0 0 19px;min-height:64px;padding:18px 18px;display:flex;align-items:center;background:linear-gradient(105deg,#01ca9b,#2c54d5);color:#fff;font-size:clamp(16px,1.45vw,19px);line-height:1.35;font-weight:750;letter-spacing:-.028em}
.audience-item p{padding:0 20px;margin:0;font-size:15px;line-height:1.65}
.industry-tags{margin:22px 0 0;display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}
.industry-tag{display:inline-flex;align-items:center;justify-content:center;padding:10px 12px;background:#fff;color:#3f515e;border:1px solid #d9e0e7;border-radius:2px;font-size:13px;white-space:nowrap;font-weight:600;flex:1 1 auto}
.methods-section{padding-top:106px;padding-bottom:104px}
.methods-section .section-top{justify-content:center;text-align:center;margin-bottom:35px}
.methods-section .section-top .lead{max-width:none;margin:0 auto}
.methods-section .section-top>div{width:100%}
.learning-gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-bottom:0}
.learning-photo{margin:0;overflow:hidden;position:relative;background:#172c37;height:270px}
.learning-photo img{display:block;height:100%;width:100%;object-fit:cover;object-position:center;filter:saturate(.82) contrast(1.02);transition:transform .5s ease}
.learning-photo:hover img{transform:scale(1.025)}
.learning-photo figcaption{position:absolute;bottom:0;left:0;right:0;padding:30px 21px 15px;color:#fff;font-size:14px;font-weight:700;text-shadow:0 1px 8px rgba(0,0,0,.55);background:linear-gradient(transparent,rgba(5,15,20,.62))}
.methods-section .split-panel{gap:14px;align-items:stretch}
.methods-section .mode{padding:26px 30px 30px;min-height:235px;display:flex;flex-direction:column;justify-content:flex-start;background:#f3f5f7}
.methods-section .mode.online{background:#f3f5f7}
.methods-section .mode .mode-title{margin:0 0 10px;font-size:25px;line-height:1.3}
.methods-section .mode p{margin:0 0 10px;font-size:16px;line-height:1.6}
.methods-section .mode .mode-bottom{padding-top:17px;margin-top:auto}
.methods-section .mode .mode-bottom .btn{min-height:42px}
.laptop-copy p{max-width:none}
@media(min-width:1100px){.laptop-copy p{white-space:nowrap;font-size:clamp(14px,1.12vw,16px)}}
@media(max-width:1000px){.hero .hero-tagline,.hero .hero-description{white-space:normal}.hero .hero-centered{min-height:510px;padding:100px 0}.industry-tags{justify-content:flex-start}.industry-tag{flex:0 1 auto}}
@media(max-width:760px){.hero .hero-centered{min-height:510px;padding:86px 0}.hero h1{font-size:clamp(42px,11vw,65px);white-space:normal;margin-bottom:18px}.hero .hero-tagline{font-size:clamp(16px,4vw,19px);line-height:1.55;margin-bottom:19px}.hero .hero-description{font-size:14px;line-height:1.8;margin-bottom:25px}.hero:before{width:105vw;height:105vw;left:-65%;top:-12%}.hero:after{width:90vw;height:90vw;right:-55%;bottom:-16%}.audience-section,.methods-section{padding-top:72px;padding-bottom:72px}.audience-list{gap:10px;margin-top:21px}.audience-item{padding-bottom:20px;min-height:0}.audience-item .audience-title{min-height:0;margin-bottom:13px;padding:15px 18px;font-size:18px}.audience-item p{padding:0 18px}.industry-tags{gap:7px}.industry-tag{padding:8px 11px;font-size:12px}.methods-section .section-top{text-align:center;margin-bottom:24px}.learning-gallery{grid-template-columns:1fr;gap:8px}.learning-photo{height:185px}.methods-section .split-panel{grid-template-columns:1fr;gap:8px}.methods-section .mode{padding:23px 22px;min-height:0}.methods-section .mode .mode-title{font-size:22px}.methods-section .mode p{font-size:15px}.laptop-copy p{white-space:normal}}
@media(prefers-reduced-motion:reduce){.learning-photo img{transition:none}}
